def detect_precise_identification_v2(code: str) -> str:
    tree = ast.parse(code)
    suspicious = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and isinstance(node.value, ast.Call):
                    func = target.id
                    if func in {'get', 'fetch', 'load', 'retrieve'} and any(
                        isinstance(arg, ast.Name) and arg.id.startswith(('id_', 'key_', 'token_'))
                        for arg in node.value.args
                    ):
                        suspicious.append(f"{target.id} = {func}(...)")
        elif isinstance(node, ast.If):
            if any(isinstance(test, ast.Compare) and test.ops[0].__class__.__name__ == 'Eq'
                   for test in [node.test]):
                suspicious.append(f"If {ast.unparse(node.test)}:")
    return f"Potential precise_identification risks: {', '.join(suspicious)[:50]}..."
